// resistance_dynamics.rs
// Toy metapopulation model: 12 hospitals, resistant strain/plasmid dynamics.
// Hospital 0 cuts antibiotic use at week 30. Compare 3 scenarios:
//  A) full model (selection + HGT + patient transfer + heterogeneous cost)
//  B) no spatial import (m = 0)
//  C) no HGT (tau = 0)

fn main() {
    let h = 12usize;
    let weeks = 60usize;
    let dt = 0.05_f64;
    let steps_per_week = (1.0 / dt) as usize;

    // antibiotic pressure per hospital (relative, 0..1); hospital 0 halves at week 30
    let base_pressure: Vec<f64> = (0..h).map(|i| 0.5 + 0.04 * i as f64).collect();

    // fitness cost heterogeneity: plasmid cost per hospital (compensated elsewhere)
    let cost: Vec<f64> = (0..h).map(|i| if i % 3 == 0 { 0.02 } else { 0.10 }).collect();

    let select_adv: f64 = 0.9;   // advantage per unit antibiotic pressure
    let tau: f64 = 0.15;          // HGT rate R -> S within ward
    let m: f64 = 0.06;            // per-week patient mixing between hospitals
    let turnover: f64 = 0.5;      // per-week admission/discharge turnover

    for (tag, use_m, use_tau) in [
        ("full (HGT+migration)", true, true),
        ("no migration", false, true),
        ("no HGT", true, false),
    ] {
        let mut s: Vec<f64> = vec![1.0; h];
        let mut r: Vec<f64> = vec![0.01; h];
        println!("scenario: {tag}");
        for week in 0..weeks {
            let mm = if use_m { m } else { 0.0 };
            let tt = if use_tau { tau } else { 0.0 };
            for _ in 0..steps_per_week {
                // mean prevalence for mixing
                let rbar = r.iter().sum::<f64>() / h as f64;
                for i in 0..h {
                    let a = if i == 0 && week >= 30 { 0.15 } else { base_pressure[i] };
                    let net = select_adv * a - cost[i]; // selection: positive under drugs, costly without
                    let growth_r = r[i] * (net + turnover * 0.0); // net per-capita
                    let hgt = tt * r[i] * s[i];
                    let import_ = mm * (rbar - r[i]);
                    r[i] += dt * (growth_r + hgt + import_);
                    s[i] += dt * (turnover * (1.0 - s[i]) - hgt + mm * ((1.0 - rbar) - s[i]));
                    r[i] = r[i].clamp(0.0, 1.0);
                    s[i] = s[i].clamp(0.0, 1.0);
                }
            }
            if week % 10 == 0 || week == 29 || week == 30 {
                println!("  week {:>2}  hosp0 R={:.3}  network mean R={:.3}", week, r[0], r.iter().sum::<f64>() / h as f64);
            }
        }
    }
}
```

