// HARD05_BIO_REASON - toy metapopulation demo (no external crates).
//
// 12 hospitals (nodes) coupled by patient transfer. In each node the
// resistant fraction x_i follows:
//
//   dx_i/dt = x_i(1-x_i) * (sel*a_i - cost_i)   // antibiotic selection minus fitness cost
//           + tau_i * x_i * (1-x_i)             // horizontal gene transfer (conjugation)
//           + m * (xbar - x_i)                  // spatial import/export of colonized patients
//
// Hospital 0 cuts antibiotic pressure at week 30 (0.35 -> 0.10).
// Plasmid fitness cost is heterogeneous across nodes, and the conjugation
// rate scales with (1 - cost) because low-cost (compensated) plasmids
// transfer and persist more readily.

const H: usize = 12;
const WEEKS: usize = 56;

fn pressure(i: usize, week: usize) -> f64 {
    if i == 0 {
        if week < 30 { 0.35 } else { 0.10 }
    } else {
        0.50 + 0.04 * i as f64
    }
}

fn cost(i: usize) -> f64 {
    if i == 0 { 0.25 } else if i % 3 == 0 { 0.03 } else { 0.12 }
}

fn simulate(mig_on: bool, hgt_on: bool) -> (Vec<f64>, Vec<f64>) {
    let sel = 0.8;
    let m = if mig_on { 0.15 } else { 0.0 };
    let dt = 0.02;
    let steps = (1.0 / dt) as usize;

    let mut x = vec![0.05; H];
    let mut x0_trace = Vec::with_capacity(WEEKS);
    let mut xbar_trace = Vec::with_capacity(WEEKS);

    for week in 0..WEEKS {
        for _ in 0..steps {
            let xbar = x.iter().sum::<f64>() / H as f64;
            for i in 0..H {
                let tau = if hgt_on { 0.12 * (1.0 - cost(i) / 0.35) } else { 0.0 };
                let local = sel * pressure(i, week) - cost(i);
                let dx = x[i] * (1.0 - x[i]) * (local + tau) + m * (xbar - x[i]);
                x[i] = (x[i] + dt * dx).clamp(0.0, 1.0);
            }
        }
        x0_trace.push(x[0]);
        xbar_trace.push(x.iter().sum::<f64>() / H as f64);
    }
    (x0_trace, xbar_trace)
}

fn main() {
    let (full0, fullbar) = simulate(true, true);
    let (nomig0, _) = simulate(false, true);
    let (nohgt0, _) = simulate(true, false);
    let (nobody0, _) = simulate(false, false);

    println!("resistant fraction at hospital 0 (cuts antibiotic use at week 30)");
    println!("week | full model | no migration | no HGT | neither");
    for week in [0usize, 10, 20, 29, 34, 41, 48, 55] {
